actions.script:
try {
    Map out = darpan.idindex.IdIndexRunHook.indexExtract(ec, tenantId, systemEnumId, connectionId, fileLocation, readStartedAt)
    if (out.error) ec.logger.warn("ID index of ${systemEnumId} extract ${fileLocation}: ${out.error}")
    records = out.records; rows = out.rows
} catch (Throwable t) {
    ec.logger.warn("ID index of ${systemEnumId} extract ${fileLocation} failed", t)
}
